def affine_hill_encrypt(pairs, K, B):
    out = []
    for x, y in pairs:
        c0 = (K[0][0] * x + K[0][1] * y + B[0]) & 0xFF #255 = mod 256?
        c1 = (K[1][0] * x + K[1][1] * y + B[1]) & 0xFF
        out.append((c0, c1))
    return out


